def converter_regras_de_safra(apps, schema_editor):
    """
    O safra virou regra com a lista de quem recebe. Cada regra de safra do
    modelo antigo (setor, setor e cargo, ou pessoa) vira uma regra nova, com o
    mesmo percentual e os mesmos meses, e com quem ela atingia ao migrar. A
    pessoa entra em uma só: a regra de pessoa primeiro, que era a que vencia.
    Regra de pessoa com zero ("não recebe") só tira a pessoa das outras.
    """
    RegraPremio = apps.get_model('folha', 'RegraPremio')
    RegraPremioSafra = apps.get_model('folha', 'RegraPremioSafra')
    MembroPremioSafra = apps.get_model('folha', 'MembroPremioSafra')
    Funcionario = apps.get_model('funcionarios', 'Funcionario')

    antigas = list(RegraPremio.objects.filter(tipo='premio_safra').select_related('setor', 'funcionario'))
    ja_colocados = {regra.funcionario_id for regra in antigas if regra.funcionario_id and not regra.valor}
    for antiga in sorted(antigas, key=lambda regra: (not regra.funcionario_id, not regra.cargo)):
        if not antiga.valor:
            continue
        if antiga.funcionario_id:
            nome, pessoas = antiga.funcionario.nome, [antiga.funcionario]
        else:
            nome = f'{antiga.setor.nome} · {antiga.cargo}' if antiga.cargo else antiga.setor.nome
            pessoas = [
                funcionario
                for funcionario in (
                    Funcionario.objects.filter(setor_id=antiga.setor_id, status='ativo')
                    .exclude(matricula__startswith='PENDENTE-')  # os gestores placeholder da importação
                )
                if not antiga.cargo or normalizar_cargo(funcionario.cargo) == normalizar_cargo(antiga.cargo)
            ]
        regra = RegraPremioSafra.objects.create(
            nome=nome[:100], percentual=antiga.valor, vigente_de=antiga.vigente_de, vigente_ate=antiga.vigente_ate,
            atualizado_por_id=antiga.atualizado_por_id,
        )
        for funcionario in pessoas:
            if funcionario.id not in ja_colocados:
                MembroPremioSafra.objects.create(regra=regra, funcionario=funcionario)
                ja_colocados.add(funcionario.id)
    RegraPremio.objects.filter(tipo='premio_safra').delete()


